        "content": "#!/usr/bin/env bun\n/**\n * JSON Validator - validates JSON input from stdin\n *\n * Usage:\n *   echo '{\"valid\": true}' | bun run src/validate-json.ts\n *   cat file.json | bun run src/validate-json.ts\n *\n * Exit codes:\n *   0 - Valid JSON\n *   1 - Invalid JSON or error\n */\n\n/**\n * Result of JSON validation\n */\nexport interface ValidationResult {\n  valid: boolean;\n  error?: string;\n  data?: unknown;\n}\n\n/**\n * Validate a JSON string and return the result\n */\nexport function validateJson(input: string): ValidationResult {\n  if (input.trim() === \"\") {\n    return {\n      valid: false,\n      error: \"Empty input\",\n    };\n  }\n\n  try {\n    const data = JSON.parse(input);\n    return {\n      valid: true,\n      data,\n    };\n  } catch (err) {\n    const errorMessage =\n      err instanceof SyntaxError ? err.message : \"Unknown parsing error\";\n    return {\n      valid: false,\n      error: errorMessage,\n    };\n  }\n}\n\n/**\n * Read all input from stdin\n */\nasync function readStdin(): Promise<string> {\n  const chunks: string[] = [];\n  const reader = Bun.stdin.stream().getReader();\n  const decoder = new TextDecoder();\n\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) break;\n    chunks.push(decoder.decode(value, { stream: true }));\n  }\n\n  // Flush any remaining bytes\n  chunks.push(decoder.decode());\n\n  return chunks.join(\"\");\n}\n\n/**\n * Main entry point - runs when script is executed directly\n */\nasync function main(): Promise<void> {\n  const input = await readStdin();\n  const result = validateJson(input);\n\n  if (result.valid) {\n    console.log(\"Valid JSON\");\n    process.exit(0);\n  } else {\n    console.error(`Invalid JSON: ${result.error}`);\n    process.exit(1);\n  }\n}\n\n// Run main when executed directly\nif (import.meta.main) {\n  main();\n}\n"
