#!/usr/bin/env bun
/**
 * JSON Validator - validates JSON input from stdin
 *
 * Usage:
 *   echo '{"valid": true}' | bun run src/validate-json.ts
 *   cat file.json | bun run src/validate-json.ts
 *
 * Exit codes:
 *   0 - Valid JSON
 *   1 - Invalid JSON or error
 */

/**
 * Result of JSON validation
 */
export interface ValidationResult {
  valid: boolean;
  error?: string;
  data?: unknown;
}

/**
 * Validate a JSON string and return the result
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim() === "") {
    return {
      valid: false,
      error: "Empty input",
    };
  }

  try {
    const data = JSON.parse(input);
    return {
      valid: true,
      data,
    };
  } catch (err) {
    const errorMessage =
      err instanceof SyntaxError ? err.message : "Unknown parsing error";
    return {
      valid: false,
      error: errorMessage,
    };
  }
}

/**
 * Read all input from stdin
 */
async function readStdin(): Promise<string> {
  const chunks: string[] = [];
  const reader = Bun.stdin.stream().getReader();
  const decoder = new TextDecoder();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(decoder.decode(value, { stream: true }));
  }

  // Flush any remaining bytes
  chunks.push(decoder.decode());

  return chunks.join("");
}

/**
 * Main entry point - runs when script is executed directly
 */
async function main(): Promise<void> {
  const input = await readStdin();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

// Run main when executed directly
if (import.meta.main) {
  main();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("validates a simple object", () => {
    const result = validateJson('{"name": "test"}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "test" });
    expect(result.error).toBeUndefined();
  });

  test("validates an array", () => {
    const result = validateJson("[1, 2, 3]");
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("validates primitive types", () => {
    expect(validateJson('"hello"').valid).toBe(true);
    expect(validateJson("123").valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("validates nested objects", () => {
    const input = '{"user": {"name": "Alice", "scores": [1, 2, 3]}}';
    const result = validateJson(input);
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({
      user: { name: "Alice", scores: [1, 2, 3] },
    });
  });

  test("rejects invalid JSON - missing closing brace", () => {
    const result = validateJson('{"name": "test"');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects invalid JSON - trailing comma", () => {
    const result = validateJson('{"name": "test",}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects invalid JSON - single quotes", () => {
    const result = validateJson("{'name': 'test'}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("accepts JSON with leading/trailing whitespace", () => {
    const result = validateJson('  \n{"valid": true}\n  ');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ valid: true });
  });
});

