        }

        const next = input.charCodeAt(pos);

        if (next === CHAR_CLOSE_BRACKET) {
          pos++;
          depth--;
          return { valid: true };
        }

        if (next === CHAR_COMMA) {
          pos++;
          skipWhitespace();

          // Check for trailing comma
          if (allowTrailingCommas && pos < len && input.charCodeAt(pos) === CHAR_CLOSE_BRACKET) {
            pos++;
            depth--;
            return { valid: true };
          }
          continue;
        }

        return {
          valid: false,
          error: "Expected comma or closing bracket in array",
          position: pos,
