/**
 * Fast JSON validity check - returns boolean only.
 *
 * Slightly faster than validateJson() when error details aren't needed.
 *
 * @param input - The JSON string to check
 * @returns true if valid JSON, false otherwise
 */
export function isValidJson(input: string): boolean {
  return validateJson(input).valid;
}

/**
 * Validates JSON and throws on error.
 *
 * @param input - The JSON string to validate
 * @param options - Optional validation configuration
 * @throws Error with validation message and position
 */
export function assertValidJson(
  input: string,
  options?: ValidatorOptions
): void {
  const result = validateJson(input, options);
  if (!result.valid) {
    const posInfo = result.position !== undefined ? ` at position ${result.position}` : "";
    throw new Error(`Invalid JSON${posInfo}: ${result.error}`);
  }
}

/**
 * Validates a file containing JSON.
 *
 * Reads the file and validates its contents.
 *
 * @param filePath - Path to the JSON file
 * @param options - Optional validation configuration
 * @returns Validation result
 */
export async function validateJsonFile(
  filePath: string,
  options?: ValidatorOptions
): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const content = await file.text();
    return validateJson(content, options);
  } catch (err) {
    return {
      valid: false,
      error: `Failed to read file: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
}

/**
 * Validates JSON from stdin.
 *
 * Useful for piping JSON to the validator.
 *
 * @param options - Optional validation configuration
 * @returns Validation result
 */
export async function validateJsonStdin(
  options?: ValidatorOptions
): Promise<ValidationResult> {
  try {
    const chunks: Uint8Array[] = [];
    for await (const chunk of Bun.stdin.stream()) {
      chunks.push(chunk);
    }
    const content = Buffer.concat(chunks).toString("utf-8");
    return validateJson(content, options);
  } catch (err) {
    return {
      valid: false,
      error: `Failed to read stdin: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
}
