/**
 * Ultra-performant JSON validation utilities.
 *
 * Performance optimizations:
 * - Direct character code operations (no intermediate string allocations)
 * - Single-pass validation where possible
 * - Early bailout on structural errors
 * - Minimal memory allocations
 * - Optional depth limiting to prevent stack overflow attacks
 */

/** Validation result with detailed error information */
export interface ValidationResult {
  valid: boolean;
  error?: string;
  position?: number;
}

/** Options for JSON validation */
export interface ValidatorOptions {
  /** Maximum nesting depth (default: 100) */
  maxDepth?: number;
  /** Maximum string length in bytes (default: unlimited) */
  maxStringLength?: number;
  /** Allow trailing commas (non-standard, default: false) */
  allowTrailingCommas?: boolean;
}

// Character codes for fast comparison
const CHAR_SPACE = 0x20;
const CHAR_TAB = 0x09;
const CHAR_NEWLINE = 0x0a;
const CHAR_CARRIAGE_RETURN = 0x0d;
const CHAR_QUOTE = 0x22;
const CHAR_COMMA = 0x2c;
const CHAR_COLON = 0x3a;
const CHAR_OPEN_BRACKET = 0x5b;
const CHAR_CLOSE_BRACKET = 0x5d;
const CHAR_OPEN_BRACE = 0x7b;
const CHAR_CLOSE_BRACE = 0x7d;
const CHAR_BACKSLASH = 0x5c;
const CHAR_MINUS = 0x2d;
const CHAR_PLUS = 0x2b;
const CHAR_PERIOD = 0x2e;
const CHAR_0 = 0x30;
const CHAR_9 = 0x39;
const CHAR_A = 0x41;
const CHAR_E = 0x45;
const CHAR_a = 0x61;
const CHAR_e = 0x65;
const CHAR_f = 0x66;
const CHAR_l = 0x6c;
const CHAR_n = 0x6e;
const CHAR_r = 0x72;
const CHAR_s = 0x73;
const CHAR_t = 0x74;
const CHAR_u = 0x75;

/**
 * Validates JSON string with high performance.
 *
 * Uses character code operations and single-pass parsing for optimal speed.
 * Does not build an AST or allocate intermediate objects.
 *
 * @param input - The JSON string to validate
 * @param options - Optional validation configuration
 * @returns Validation result with error details if invalid
 */
export function validateJson(
  input: string,
  options: ValidatorOptions = {}
): ValidationResult {
  const maxDepth = options.maxDepth ?? 100;
  const maxStringLength = options.maxStringLength ?? Infinity;
  const allowTrailingCommas = options.allowTrailingCommas ?? false;

  const len = input.length;
  let pos = 0;
  let depth = 0;

  // Skip whitespace helper - inlined for performance
  function skipWhitespace(): void {
    while (pos < len) {
      const c = input.charCodeAt(pos);
      if (
        c !== CHAR_SPACE &&
        c !== CHAR_TAB &&
        c !== CHAR_NEWLINE &&
        c !== CHAR_CARRIAGE_RETURN
      ) {
        break;
      }
      pos++;
    }
  }

  // Parse a string value
  function parseString(): ValidationResult {
    const start = pos;
    pos++; // skip opening quote

    let stringLen = 0;

    while (pos < len) {
      const c = input.charCodeAt(pos);

      if (c === CHAR_QUOTE) {
        pos++;
        return { valid: true };
      }

      if (c === CHAR_BACKSLASH) {
        pos++;
        if (pos >= len) {
          return {
            valid: false,
            error: "Unexpected end of string",
            position: pos,
          };
        }

        const escaped = input.charCodeAt(pos);
        // Valid escape sequences: " \ / b f n r t u
        if (
          escaped !== CHAR_QUOTE &&
          escaped !== CHAR_BACKSLASH &&
          escaped !== 0x2f && // /
          escaped !== 0x62 && // b
          escaped !== CHAR_f &&
          escaped !== CHAR_n &&
          escaped !== CHAR_r &&
          escaped !== CHAR_t &&
          escaped !== CHAR_u
        ) {
          return {
            valid: false,
            error: `Invalid escape sequence: \\${input[pos]}`,
            position: pos - 1,
          };
        }

        if (escaped === CHAR_u) {
          // Unicode escape: \uXXXX
          if (pos + 4 >= len) {
            return {
              valid: false,
              error: "Invalid unicode escape sequence",
              position: pos,
            };
          }
          for (let i = 1; i <= 4; i++) {
            const hex = input.charCodeAt(pos + i);
            if (
              !(
                (hex >= CHAR_0 && hex <= CHAR_9) ||
                (hex >= CHAR_A && hex <= 0x46) ||
                (hex >= CHAR_a && hex <= CHAR_f)
              )
            ) {
              return {
                valid: false,
                error: "Invalid unicode escape sequence",
                position: pos,
              };
            }
          }
          pos += 4;
        }
        stringLen++;
        pos++;
        continue;
      }

      // Control characters are not allowed
      if (c < 0x20) {
        return {
          valid: false,
          error: "Invalid control character in string",
          position: pos,
        };
      }

      stringLen++;
      if (stringLen > maxStringLength) {
        return {
          valid: false,
          error: `String exceeds maximum length of ${maxStringLength}`,
          position: start,
        };
      }

      pos++;
    }

    return {
      valid: false,
      error: "Unterminated string",
      position: start,
    };
  }

  // Parse a number
  function parseNumber(): ValidationResult {
    const start = pos;

    // Optional minus sign
    if (input.charCodeAt(pos) === CHAR_MINUS) {
      pos++;
    }

    if (pos >= len) {
      return {
        valid: false,
        error: "Invalid number",
        position: start,
      };
    }

    // Integer part
    const firstDigit = input.charCodeAt(pos);
    if (firstDigit === CHAR_0) {
      pos++;
      // Leading zero must not be followed by another digit
      if (pos < len) {
        const next = input.charCodeAt(pos);
        if (next >= CHAR_0 && next <= CHAR_9) {
          return {
            valid: false,
            error: "Leading zeros not allowed",
            position: start,
          };
        }
      }
    } else if (firstDigit >= CHAR_0 + 1 && firstDigit <= CHAR_9) {
      pos++;
      while (pos < len) {
        const c = input.charCodeAt(pos);
        if (c < CHAR_0 || c > CHAR_9) break;
        pos++;
      }
    } else {
      return {
        valid: false,
        error: "Invalid number",
        position: start,
      };
    }

    // Fractional part
    if (pos < len && input.charCodeAt(pos) === CHAR_PERIOD) {
      pos++;
      if (pos >= len) {
        return {
          valid: false,
          error: "Invalid number: expected digit after decimal point",
          position: pos,
        };
      }

      const digitAfterDot = input.charCodeAt(pos);
      if (digitAfterDot < CHAR_0 || digitAfterDot > CHAR_9) {
        return {
          valid: false,
          error: "Invalid number: expected digit after decimal point",
          position: pos,
        };
      }

      while (pos < len) {
        const c = input.charCodeAt(pos);
        if (c < CHAR_0 || c > CHAR_9) break;
        pos++;
      }
    }

    // Exponent part
    if (pos < len) {
      const expChar = input.charCodeAt(pos);
      if (expChar === CHAR_E || expChar === CHAR_e) {
        pos++;
        if (pos >= len) {
          return {
            valid: false,
            error: "Invalid number: expected digit in exponent",
            position: pos,
          };
        }

        const signOrDigit = input.charCodeAt(pos);
        if (signOrDigit === CHAR_PLUS || signOrDigit === CHAR_MINUS) {
          pos++;
        }

        if (pos >= len) {
          return {
            valid: false,
            error: "Invalid number: expected digit in exponent",
            position: pos,
          };
        }

        const expDigit = input.charCodeAt(pos);
        if (expDigit < CHAR_0 || expDigit > CHAR_9) {
          return {
            valid: false,
            error: "Invalid number: expected digit in exponent",
            position: pos,
          };
        }

        while (pos < len) {
          const c = input.charCodeAt(pos);
          if (c < CHAR_0 || c > CHAR_9) break;
          pos++;
        }
      }
    }

    return { valid: true };
  }

  // Parse literal keywords (true, false, null)
  function parseLiteral(
    expected: string,
    startPos: number
  ): ValidationResult {
    if (pos + expected.length > len) {
      return {
        valid: false,
        error: `Unexpected token`,
        position: startPos,
      };
    }

    for (let i = 0; i < expected.length; i++) {
      if (input.charCodeAt(pos + i) !== expected.charCodeAt(i)) {
        return {
          valid: false,
          error: `Unexpected token`,
          position: startPos,
        };
      }
    }

    pos += expected.length;
    return { valid: true };
  }

  // Parse any JSON value
  function parseValue(): ValidationResult {
    skipWhitespace();

    if (pos >= len) {
      return {
        valid: false,
        error: "Unexpected end of input",
        position: pos,
      };
    }

    const c = input.charCodeAt(pos);

    // Object
    if (c === CHAR_OPEN_BRACE) {
      depth++;
      if (depth > maxDepth) {
        return {
          valid: false,
          error: `Maximum depth of ${maxDepth} exceeded`,
          position: pos,
        };
      }
      pos++;
      skipWhitespace();

      if (pos < len && input.charCodeAt(pos) === CHAR_CLOSE_BRACE) {
        pos++;
        depth--;
        return { valid: true };
      }

      while (true) {
        skipWhitespace();

        if (pos >= len) {
          return {
            valid: false,
            error: "Unexpected end of input in object",
            position: pos,
          };
        }

        if (input.charCodeAt(pos) !== CHAR_QUOTE) {
          return {
            valid: false,
            error: "Expected property name",
            position: pos,
          };
        }

        const keyResult = parseString();
        if (!keyResult.valid) return keyResult;

        skipWhitespace();

        if (pos >= len || input.charCodeAt(pos) !== CHAR_COLON) {
          return {
            valid: false,
            error: "Expected colon after property name",
            position: pos,
          };
        }
        pos++;

        const valueResult = parseValue();
        if (!valueResult.valid) return valueResult;

        skipWhitespace();

        if (pos >= len) {
          return {
            valid: false,
            error: "Unexpected end of input in object",
            position: pos,
          };
        }

        const next = input.charCodeAt(pos);

        if (next === CHAR_CLOSE_BRACE) {
          pos++;
          depth--;
          return { valid: true };
        }

        if (next === CHAR_COMMA) {
          pos++;
          skipWhitespace();

          // Check for trailing comma
          if (allowTrailingCommas && pos < len && input.charCodeAt(pos) === CHAR_CLOSE_BRACE) {
            pos++;
            depth--;
            return { valid: true };
          }
          continue;
        }

        return {
          valid: false,
          error: "Expected comma or closing brace in object",
          position: pos,
        };
      }
    }

    // Array
    if (c === CHAR_OPEN_BRACKET) {
      depth++;
      if (depth > maxDepth) {
        return {
          valid: false,
          error: `Maximum depth of ${maxDepth} exceeded`,
          position: pos,
        };
      }
      pos++;
      skipWhitespace();

      if (pos < len && input.charCodeAt(pos) === CHAR_CLOSE_BRACKET) {
        pos++;
        depth--;
        return { valid: true };
      }

      while (true) {
        const elementResult = parseValue();
        if (!elementResult.valid) return elementResult;

        skipWhitespace();

        if (pos >= len) {
          return {
            valid: false,
            error: "Unexpected end of input in array",
            position: pos,
          };
        }

        const next = input.charCodeAt(pos);

        if (next === CHAR_CLOSE_BRACKET) {
          pos++;
          depth--;
          return { valid: true };
        }

        if (next === CHAR_COMMA) {
          pos++;
          skipWhitespace();

          // Check for trailing comma
          if (allowTrailingCommas && pos < len && input.charCodeAt(pos) === CHAR_CLOSE_BRACKET) {
            pos++;
            depth--;
            return { valid: true };
          }
          continue;
        }

        return {
          valid: false,
          error: "Expected comma or closing bracket in array",
          position: pos,
        };
      }
    }

    // String
    if (c === CHAR_QUOTE) {
      return parseString();
    }

    // Number
    if (c === CHAR_MINUS || (c >= CHAR_0 && c <= CHAR_9)) {
      return parseNumber();
    }

    // true
    if (c === CHAR_t) {
      return parseLiteral("true", pos);
    }

    // false
    if (c === CHAR_f) {
      return parseLiteral("false", pos);
    }

    // null
    if (c === CHAR_n) {
      return parseLiteral("null", pos);
    }

    return {
      valid: false,
      error: `Unexpected character: ${input[pos]}`,
      position: pos,
    };
  }

  // Empty input
  skipWhitespace();
  if (pos >= len) {
    return {
      valid: false,
      error: "Empty input",
      position: 0,
    };
  }

  // Parse root value
  const result = parseValue();
  if (!result.valid) {
    return result;
  }

  // Check for trailing content
  skipWhitespace();
  if (pos < len) {
    return {
      valid: false,
      error: "Unexpected content after JSON value",
      position: pos,
    };
  }

  return { valid: true };
}

/**
 * Fast JSON validity check - returns boolean only.
 *
 * Slightly faster than validateJson() when error details aren't needed.
 *
 * @param input - The JSON string to check
 * @returns true if valid JSON, false otherwise
 */
export function isValidJson(input: string): boolean {
  return validateJson(input).valid;
}

/**
 * Validates JSON and throws on error.
 *
 * @param input - The JSON string to validate
 * @param options - Optional validation configuration
 * @throws Error with validation message and position
 */
export function assertValidJson(
  input: string,
  options?: ValidatorOptions
): void {
  const result = validateJson(input, options);
  if (!result.valid) {
    const posInfo = result.position !== undefined ? ` at position ${result.position}` : "";
    throw new Error(`Invalid JSON${posInfo}: ${result.error}`);
  }
}

/**
 * Validates a file containing JSON.
 *
 * Reads the file and validates its contents.
 *
 * @param filePath - Path to the JSON file
 * @param options - Optional validation configuration
 * @returns Validation result
 */
export async function validateJsonFile(
  filePath: string,
  options?: ValidatorOptions
): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const content = await file.text();
    return validateJson(content, options);
  } catch (err) {
    return {
      valid: false,
      error: `Failed to read file: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
}

/**
 * Validates JSON from stdin.
 *
 * Useful for piping JSON to the validator.
 *
 * @param options - Optional validation configuration
 * @returns Validation result
 */
export async function validateJsonStdin(
  options?: ValidatorOptions
): Promise<ValidationResult> {
  try {
    const chunks: Uint8Array[] = [];
    for await (const chunk of Bun.stdin.stream()) {
      chunks.push(chunk);
    }
    const content = Buffer.concat(chunks).toString("utf-8");
    return validateJson(content, options);
  } catch (err) {
    return {
      valid: false,
      error: `Failed to read stdin: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
}

import { describe, expect, test } from "bun:test";
import {
  validateJson,
  isValidJson,
  assertValidJson,
  type ValidationResult,
} from "./json-validator";

describe("json-validator", () => {
  describe("validateJson", () => {
    describe("valid JSON", () => {
      test("empty object", () => {
        expect(validateJson("{}")).toEqual({ valid: true });
      });

      test("empty array", () => {
        expect(validateJson("[]")).toEqual({ valid: true });
      });

      test("null", () => {
        expect(validateJson("null")).toEqual({ valid: true });
      });

      test("true", () => {
        expect(validateJson("true")).toEqual({ valid: true });
      });

      test("false", () => {
        expect(validateJson("false")).toEqual({ valid: true });
      });

      test("string", () => {
        expect(validateJson('"hello"')).toEqual({ valid: true });
      });

      test("integer", () => {
        expect(validateJson("42")).toEqual({ valid: true });
      });

      test("negative integer", () => {
        expect(validateJson("-42")).toEqual({ valid: true });
      });

      test("float", () => {
        expect(validateJson("3.14")).toEqual({ valid: true });
      });

      test("scientific notation", () => {
        expect(validateJson("1.5e10")).toEqual({ valid: true });
        expect(validateJson("1.5E10")).toEqual({ valid: true });
        expect(validateJson("1.5e+10")).toEqual({ valid: true });
        expect(validateJson("1.5e-10")).toEqual({ valid: true });
      });

      test("object with properties", () => {
        expect(validateJson('{"name": "test", "value": 123}')).toEqual({
          valid: true,
        });
      });

      test("array with elements", () => {
        expect(validateJson("[1, 2, 3]")).toEqual({ valid: true });
      });

      test("nested structures", () => {
        const json = '{"users": [{"name": "Alice"}, {"name": "Bob"}]}';
        expect(validateJson(json)).toEqual({ valid: true });
      });

      test("string with escape sequences", () => {
        expect(validateJson('"hello\\nworld"')).toEqual({ valid: true });
        expect(validateJson('"path\\\\to\\\\file"')).toEqual({ valid: true });
        expect(validateJson('"quote: \\""')).toEqual({ valid: true });
        expect(validateJson('"tab\\there"')).toEqual({ valid: true });
      });

      test("string with unicode escape", () => {
        expect(validateJson('"\\u0041"')).toEqual({ valid: true });
        expect(validateJson('"\\u00e9"')).toEqual({ valid: true });
      });

      test("whitespace handling", () => {
        expect(validateJson("  { }  ")).toEqual({ valid: true });
        expect(validateJson("[\n  1,\n  2\n]")).toEqual({ valid: true });
        expect(validateJson('{\t"a":\t1\t}')).toEqual({ valid: true });
      });

      test("zero", () => {
        expect(validateJson("0")).toEqual({ valid: true });
        expect(validateJson("-0")).toEqual({ valid: true });
        expect(validateJson("0.0")).toEqual({ valid: true });
      });
    });

    describe("invalid JSON", () => {
      test("empty input", () => {
        const result = validateJson("");
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Empty input");
      });

      test("whitespace only", () => {
        const result = validateJson("   ");
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Empty input");
      });

      test("unclosed object", () => {
        const result = validateJson('{"name": "test"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("Unexpected end");
      });

      test("unclosed array", () => {
        const result = validateJson("[1, 2, 3");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("Unexpected end");
      });

      test("unclosed string", () => {
        const result = validateJson('"hello');
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Unterminated string");
      });

      test("trailing comma in object", () => {
        const result = validateJson('{"a": 1,}');
        expect(result.valid).toBe(false);
      });

      test("trailing comma in array", () => {
        const result = validateJson("[1, 2,]");
        expect(result.valid).toBe(false);
      });

      test("leading zeros", () => {
        const result = validateJson("007");
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Leading zeros not allowed");
      });

      test("invalid number format", () => {
        expect(validateJson("1.").valid).toBe(false);
        expect(validateJson(".1").valid).toBe(false);
        expect(validateJson("1e").valid).toBe(false);
      });

      test("single quotes", () => {
        const result = validateJson("'hello'");
        expect(result.valid).toBe(false);
      });

      test("unquoted property name", () => {
        const result = validateJson("{name: 1}");
        expect(result.valid).toBe(false);
      });

      test("invalid escape sequence", () => {
        const result = validateJson('"\\x41"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("Invalid escape");
      });

      test("invalid unicode escape", () => {
        const result = validateJson('"\\u00GG"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("unicode");
      });

      test("control characters in string", () => {
        const result = validateJson('"hello\nworld"');
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Invalid control character in string");
      });

      test("trailing content", () => {
        const result = validateJson("{}extra");
        expect(result.valid).toBe(false);
        expect(result.error).toBe("Unexpected content after JSON value");
      });

      test("multiple values", () => {
        const result = validateJson("1 2");
        expect(result.valid).toBe(false);
      });

      test("undefined keyword", () => {
        const result = validateJson("undefined");
        expect(result.valid).toBe(false);
      });

      test("NaN", () => {
        const result = validateJson("NaN");
        expect(result.valid).toBe(false);
      });

      test("Infinity", () => {
        const result = validateJson("Infinity");
        expect(result.valid).toBe(false);
      });
    });

    describe("options", () => {
      test("maxDepth limits nesting", () => {
        const deepJson = '{"a":{"b":{"c":{"d":1}}}}';
        expect(validateJson(deepJson, { maxDepth: 10 })).toEqual({ valid: true });

        const result = validateJson(deepJson, { maxDepth: 2 });
        expect(result.valid).toBe(false);
        expect(result.error).toContain("Maximum depth");
      });

      test("maxStringLength limits string size", () => {
        const json = '"' + "a".repeat(100) + '"';
        expect(validateJson(json, { maxStringLength: 200 })).toEqual({ valid: true });

        const result = validateJson(json, { maxStringLength: 50 });
        expect(result.valid).toBe(false);
        expect(result.error).toContain("exceeds maximum length");
      });

      test("allowTrailingCommas in object", () => {
        const json = '{"a": 1,}';
        expect(validateJson(json, { allowTrailingCommas: false }).valid).toBe(false);
        expect(validateJson(json, { allowTrailingCommas: true })).toEqual({ valid: true });
      });

      test("allowTrailingCommas in array", () => {
        const json = "[1, 2, 3,]";
        expect(validateJson(json, { allowTrailingCommas: false }).valid).toBe(false);
        expect(validateJson(json, { allowTrailingCommas: true })).toEqual({ valid: true });
      });
    });

    describe("error positions", () => {
      test("reports correct position for unclosed string", () => {
        const result = validateJson('{"key": "value');
        expect(result.valid).toBe(false);
        expect(result.position).toBe(8); // Position of the opening quote
      });

      test("reports correct position for invalid character", () => {
        const result = validateJson('{"key": @invalid}');
        expect(result.valid).toBe(false);
        expect(result.position).toBe(8);
      });
    });
  });

  describe("isValidJson", () => {
    test("returns true for valid JSON", () => {
      expect(isValidJson("{}")).toBe(true);
      expect(isValidJson("[]")).toBe(true);
      expect(isValidJson("null")).toBe(true);
      expect(isValidJson('{"key": "value"}')).toBe(true);
    });

    test("returns false for invalid JSON", () => {
      expect(isValidJson("")).toBe(false);
      expect(isValidJson("{")).toBe(false);
      expect(isValidJson("undefined")).toBe(false);
    });
  });

  describe("assertValidJson", () => {
    test("does not throw for valid JSON", () => {
      expect(() => assertValidJson("{}")).not.toThrow();
      expect(() => assertValidJson("null")).not.toThrow();
    });

    test("throws for invalid JSON", () => {
      expect(() => assertValidJson("")).toThrow("Invalid JSON");
      expect(() => assertValidJson("{")).toThrow("Invalid JSON");
    });

    test("error message includes position", () => {
      expect(() => assertValidJson('{"key": @}')).toThrow("at position 8");
    });
  });

  describe("performance characteristics", () => {
    test("handles large arrays efficiently", () => {
      const largeArray = "[" + Array(10000).fill("1").join(",") + "]";
      const start = performance.now();
      const result = validateJson(largeArray);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(100); // Should complete in under 100ms
    });

    test("handles deeply nested structures", () => {
      const depth = 50;
      const nested = "{".repeat(depth) + '"a":1' + "}".repeat(depth);
      const result = validateJson(nested);

      expect(result.valid).toBe(true);
    });

    test("handles long strings efficiently", () => {
      const longString = '"' + "x".repeat(100000) + '"';
      const start = performance.now();
      const result = validateJson(longString);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(100);
    });
  });
});

